const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Dublin geometry and time periods
  const dublin = ee.Geometry.Point([-6.26, 53.35]).buffer(15000); // 15km radius

  const date1984Start = '1984-11-01';
  const date1984End = '1984-11-30';
  const date2022Start = '2022-11-01';
  const date2022End = '2022-11-30';

  // 2. Cloud masking functions
  function maskL5(image) {
    const qa = image.select('QA_PIXEL');
    const mask = qa.bitwiseAnd(1 << 3).eq(0).and(qa.bitwiseAnd(1 << 4).eq(0));
    return image.updateMask(mask);
  }

  function maskL8(image) {
    const qa = image.select('QA_PIXEL');
    const mask = qa.bitwiseAnd(1 << 3).eq(0).and(qa.bitwiseAnd(1 << 4).eq(0));
    return image.updateMask(mask);
  }

  // 3. Load Landsat 5 for 1984
  let col1984 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(dublin)
    .filterDate(date1984Start, date1984End)
    .map(maskL5);

  const size1984 = await col1984.size().getInfo();
  console.log(`1984 Images found: ${size1984}`);

  if (size1984 === 0) {
    console.log('No data for November 1984.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Load Landsat 8/9 for 2022
  let col2022 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
    .filterBounds(dublin)
    .filterDate(date2022Start, date2022End)
    .map(maskL8);

  let size2022 = await col2022.size().getInfo();
  console.log(`2022 Images found (L9): ${size2022}`);

  if (size2022 === 0) {
    col2022 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(dublin)
      .filterDate(date2022Start, date2022End)
      .map(maskL8);
    size2022 = await col2022.size().getInfo();
    console.log(`2022 Images found (L8): ${size2022}`);
  }

  if (size2022 === 0) {
    console.log('No data for November 2022.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Calculate NDBI (Built-up index) = (SWIR - NIR) / (SWIR + NIR)
  function addNDBI_L5(image) {
    const ndbi = image.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDBI');
    return image.addBands(ndbi);
  }

  function addNDBI_L8(image) {
    const ndbi = image.normalizedDifference(['SR_B6', 'SR_B5']).rename('NDBI');
    return image.addBands(ndbi);
  }

  const img1984 = col1984.map(addNDBI_L5).select('NDBI').median();
  const img2022 = col2022.map(addNDBI_L8).select('NDBI').median();

  // 6. Calculate built-up area (NDBI > 0 threshold)
  const builtup1984 = img1984.gt(0);
  const builtup2022 = img2022.gt(0);

  // 7. Check valid pixels
  const count1984Result = await builtup1984.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: dublin,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const count2022Result = await builtup2022.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: dublin,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const count1984 = count1984Result.NDBI || 0;
  const count2022 = count2022Result.NDBI || 0;

  console.log(`Valid pixels 1984: ${count1984}, 2022: ${count2022}`);

  if (count1984 === 0 || count2022 === 0) {
    console.log('No valid pixels after masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 8. Calculate built-up area in pixels
  const area1984Result = await builtup1984.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: dublin,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const area2022Result = await builtup2022.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: dublin,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const area1984 = area1984Result.NDBI;
  const area2022 = area2022Result.NDBI;

  console.log(`Built-up pixels 1984: ${area1984}`);
  console.log(`Built-up pixels 2022: ${area2022}`);

  if (area1984 === null || area1984 === undefined || area2022 === null || area2022 === undefined) {
    console.log('Calculation failed.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 9. Final answer
  if (area2022 > area1984) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
